input.new_string:
const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

// Only the sword (base 100 G) is covered by a test so far.
const ITEM_BASE_PREMIUM = 100;

const quote = (step: Step): QuoteResult => {
  const policyBasePremium = step.items.length * ITEM_BASE_PREMIUM;
  const withFirstInsurance =
    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
  return { premium: withFirstInsurance + PROCESSING_FEE };
};

